// Generated from src/registry/sources/control-ui/recipes/track-highlight.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const trackHighlightKnobs = [
  "--cui-track-highlight-radius",
  "--cui-track-highlight-background",
  "--cui-track-highlight-hover-background",
  "--cui-track-highlight-ring-color",
  "--cui-track-highlight-shadow",
  "--cui-track-highlight-transition-duration",
] as const;
export type TrackHighlightKnobStyle = Partial<Record<(typeof trackHighlightKnobs)[number], string>>;

export type TrackHighlightOptions = {
  itemSelector: string;
  activeSelector: string;
  range?: boolean;
  followHover?: boolean;
};

type Box = { x: number; y: number; w: number; h: number };
type LayerState = { ready: boolean; last: Box };

const STABLE_EPSILON = 0.5;

const MAX_FOLLOW_FRAMES = 90;

function isHighlightable(node: Element | null): node is HTMLElement {
  return (
    node instanceof HTMLElement &&
    !node.matches(
      ':disabled, [aria-disabled="true"], [data-disabled]:not([data-disabled="false"]), :has([role="checkbox"][data-disabled])',
    ) &&
    node.checkVisibility()
  );
}

export function createTrackHighlight(
  track: HTMLElement,
  highlight: HTMLElement,
  options: TrackHighlightOptions,
  hoverHighlight?: HTMLElement,
): () => void {
  const { itemSelector, activeSelector, range = false, followHover = true } = options;
  highlight.setAttribute("data-measured", "");

  let hovered: HTMLElement | null = null;
  let focused: HTMLElement | null = null;
  let rafId = 0;
  let followFrames = 0;
  const activeLayer: LayerState = { ready: false, last: { x: 0, y: 0, w: 0, h: 0 } };
  const hoverLayer: LayerState = { ready: false, last: { x: 0, y: 0, w: 0, h: 0 } };

  function belongsToTrack(item: HTMLElement): boolean {
    return track.hasAttribute("data-track") ? item.closest("[data-track]") === track : track.contains(item);
  }

  function measureBox(target: HTMLElement, trackRect: DOMRect): Box {
    const rect = target.getBoundingClientRect();
    return {
      x: rect.left - trackRect.left + track.scrollLeft - track.clientLeft,
      y: rect.top - trackRect.top + track.scrollTop - track.clientTop,
      w: rect.width,
      h: rect.height,
    };
  }

  function resolveActiveBox(trackRect: DOMRect): Box | null {
    if (track.dataset.track === "hover") return null;
    const actives = Array.from(track.querySelectorAll<HTMLElement>(activeSelector)).filter(
      (item) => isHighlightable(item) && belongsToTrack(item),
    );
    const firstActive = actives[0];
    if (!firstActive) return null;
    if (!range) return measureBox(firstActive, trackRect);
    let box = measureBox(firstActive, trackRect);
    for (const active of actives.slice(1)) {
      const b = measureBox(active, trackRect);
      const left = Math.min(box.x, b.x);
      const top = Math.min(box.y, b.y);
      const right = Math.max(box.x + box.w, b.x + b.w);
      const bottom = Math.max(box.y + box.h, b.y + b.h);
      box = { x: left, y: top, w: right - left, h: bottom - top };
    }
    return box;
  }

  function resolveHoveredBox(trackRect: DOMRect): Box | null {
    const target = focused ?? hovered;
    if (!followHover || !target || !belongsToTrack(target) || !isHighlightable(target)) return null;
    return measureBox(target, trackRect);
  }

  function place(element: HTMLElement, state: LayerState, next: Box | null, visible: boolean): boolean {
    if (!next) {
      element.removeAttribute("data-visible");
      return false;
    }

    const moved =
      Math.abs(next.x - state.last.x) > STABLE_EPSILON ||
      Math.abs(next.y - state.last.y) > STABLE_EPSILON ||
      Math.abs(next.w - state.last.w) > STABLE_EPSILON ||
      Math.abs(next.h - state.last.h) > STABLE_EPSILON;
    state.last = next;

    if (!state.ready) element.style.transition = "none";
    element.style.left = `${next.x}px`;
    element.style.top = `${next.y}px`;
    element.style.right = `${track.clientWidth - (next.x + next.w)}px`;
    element.style.bottom = `${track.clientHeight - (next.y + next.h)}px`;
    element.toggleAttribute("data-visible", visible);

    if (!state.ready) {
      void element.offsetWidth;
      element.style.transition = "";
      state.ready = true;
    }
    return moved;
  }

  function placeHighlightLayers(): boolean {
    const trackRect = track.getBoundingClientRect();
    const activeBox = resolveActiveBox(trackRect);
    const hoveredBox = resolveHoveredBox(trackRect);
    const target = focused ?? hovered;
    const isAway = hoveredBox !== null && target !== null && !target.matches(activeSelector);
    track.toggleAttribute("data-track-hover", isAway);

    const activeMoved = place(
      highlight,
      activeLayer,
      hoverHighlight ? activeBox : (hoveredBox ?? activeBox),
      Boolean(activeBox || hoveredBox),
    );
    if (!hoverHighlight) highlight.toggleAttribute("data-hover", isAway);
    const hoverMoved = hoverHighlight ? place(hoverHighlight, hoverLayer, hoveredBox ?? activeBox, Boolean(hoveredBox)) : false;

    return activeMoved || hoverMoved;
  }

  function scheduleFollow(): void {
    followFrames = 0;
    if (rafId) return;
    const step = () => {
      rafId = 0;
      const moved = placeHighlightLayers();
      if (!moved || followFrames >= MAX_FOLLOW_FRAMES) return;
      followFrames += 1;
      rafId = requestAnimationFrame(step);
    };
    rafId = requestAnimationFrame(step);
  }

  const onPointerOver = (event: PointerEvent) => {
    if (event.pointerType === "touch" || !(event.target instanceof Element)) return;
    const item = event.target.closest<HTMLElement>(itemSelector);
    const nextHovered = isHighlightable(item) && belongsToTrack(item) ? item : null;
    if (nextHovered === hovered) return;
    hovered = nextHovered;
    scheduleFollow();
  };

  const onPointerLeave = () => {
    if (!hovered) return;
    hovered = null;
    scheduleFollow();
  };

  const onFocusChange = () => {
    const activeElement = document.activeElement;
    const item = activeElement?.closest<HTMLElement>(itemSelector);
    focused = item && belongsToTrack(item) && activeElement?.matches(":focus-visible") && isHighlightable(item) ? item : null;
    scheduleFollow();
  };

  const onFocusOut = () => {
    focused = null;
    scheduleFollow();
  };

  if (followHover) {
    if (matchMedia("(hover: hover)").matches) {
      hovered =
        Array.from(track.querySelectorAll<HTMLElement>(itemSelector)).find(
          (item) => item.matches(":hover") && isHighlightable(item) && belongsToTrack(item),
        ) ?? null;
    }
    onFocusChange();
    track.addEventListener("pointerover", onPointerOver);
    track.addEventListener("pointerleave", onPointerLeave);
    track.addEventListener("focusin", onFocusChange);
    track.addEventListener("focusout", onFocusOut);
  }

  const resizeObserver = new ResizeObserver(() => scheduleFollow());
  resizeObserver.observe(track);

  const mutationObserver = new MutationObserver(() => scheduleFollow());
  mutationObserver.observe(track, {
    subtree: true,
    childList: true,
    attributes: true,
    attributeFilter: [
      "data-selected",
      "aria-selected",
      "data-active",
      "data-state",
      "data-disabled",
      "aria-disabled",
      "disabled",
      "data-track",
    ],
  });

  scheduleFollow();

  return () => {
    highlight.removeAttribute("data-measured");
    if (rafId) cancelAnimationFrame(rafId);
    track.removeEventListener("pointerover", onPointerOver);
    track.removeEventListener("pointerleave", onPointerLeave);
    track.removeEventListener("focusin", onFocusChange);
    track.removeEventListener("focusout", onFocusOut);
    track.removeAttribute("data-track-hover");
    resizeObserver.disconnect();
    mutationObserver.disconnect();
    for (const element of [highlight, hoverHighlight]) {
      if (!element) continue;
      for (const property of ["top", "left", "right", "bottom"]) element.style.removeProperty(property);
      element.removeAttribute("data-visible");
      element.removeAttribute("data-hover");
    }
  };
}

let anchorTransitionsSupported: boolean | undefined;

export function supportsAnchorTransitions(): boolean {
  if (anchorTransitionsSupported !== undefined) return anchorTransitionsSupported;
  if (!CSS.supports("(anchor-name: --_track-transition-probe) and (anchor-scope: --_track-transition-probe)")) {
    anchorTransitionsSupported = false;
    return false;
  }

  const probeTrack = document.createElement("div");
  probeTrack.style.cssText = "position:fixed;left:-10000px;top:0;visibility:hidden;anchor-scope:--_track-transition-probe";
  const initialAnchor = document.createElement("div");
  initialAnchor.style.cssText = "position:absolute;top:0;width:1px;height:1px;anchor-name:--_track-transition-probe";
  const nextAnchor = document.createElement("div");
  nextAnchor.style.cssText = "position:absolute;top:10px;width:1px;height:1px";
  const probeHighlight = document.createElement("div");
  probeHighlight.style.cssText = "position:absolute;top:anchor(--_track-transition-probe top);width:1px;height:1px";
  probeHighlight.style.setProperty("transition", "top 1s linear", "important");
  probeTrack.append(initialAnchor, nextAnchor, probeHighlight);
  document.body.append(probeTrack);
  try {
    void probeHighlight.offsetTop;
    initialAnchor.style.anchorName = "none";
    nextAnchor.style.anchorName = "--_track-transition-probe";
    anchorTransitionsSupported = probeHighlight.getAnimations().length > 0;
    return anchorTransitionsSupported;
  } finally {
    probeTrack.remove();
  }
}

"use client";

import type { ComponentProps, CSSProperties, ReactNode, RefObject } from "react";
import { useEffect, useRef } from "react";
import { supportsAnchorTransitions } from "@/components/control-ui/extensions/supports-anchor-transitions";
import type { TrackHighlightKnobStyle } from "@/components/control-ui/knob-contracts/track-highlight-knobs";
import { cn } from "@/components/control-ui/lib/cn";

const trackHighlightStructureClasses = "pointer-events-none absolute -z-10";
const defaultItemSelector = "[data-track-item]";
const defaultActiveSelector = '[data-track-item][data-active="true"]';
const loadTrackHighlight = () => import("@/components/control-ui/extensions/create-track-highlight");

export type TrackHighlightProps = Omit<ComponentProps<"div">, "children" | "ref" | "style"> & {
  trackRef?: RefObject<HTMLElement | null>;
  itemSelector?: string;
  activeSelector?: string;
  range?: boolean;
  followHover?: boolean;
  hoverClassName?: string;
  children?: ReactNode;
  style?: CSSProperties & TrackHighlightKnobStyle;
};

export function TrackHighlight({
  trackRef,
  itemSelector = defaultItemSelector,
  activeSelector = defaultActiveSelector,
  range,
  followHover,
  hoverClassName,
  className,
  style,
  children,
  ...props
}: TrackHighlightProps) {
  const ref = useRef<HTMLDivElement>(null);
  const hoverRef = useRef<HTMLDivElement>(null);
  const layered = Boolean(hoverClassName);
  const usesAnchorAnatomy =
    !trackRef &&
    !range &&
    !layered &&
    followHover !== false &&
    itemSelector === defaultItemSelector &&
    activeSelector === defaultActiveSelector;

  useEffect(() => {
    const highlight = ref.current;
    const track = trackRef?.current ?? highlight?.parentElement;
    if (!track || !highlight) return;
    const usesAnchors = usesAnchorAnatomy && track.hasAttribute("data-track") && supportsAnchorTransitions();
    if (usesAnchors) return;
    const hoverHighlight = layered ? (hoverRef.current ?? undefined) : undefined;
    let cancelled = false;
    let dispose: (() => void) | undefined;
    loadTrackHighlight().then(({ createTrackHighlight }) => {
      if (cancelled) return;
      dispose = createTrackHighlight(track, highlight, { itemSelector, activeSelector, range, followHover }, hoverHighlight);
    });
    return () => {
      cancelled = true;
      dispose?.();
    };
  }, [trackRef, itemSelector, activeSelector, range, followHover, layered, usesAnchorAnatomy]);

  return (
    <>
      <div
        {...props}
        ref={ref}
        data-control-ui="track-highlight"
        data-control-family="track-highlight"
        data-slot="root"
        data-positioning={usesAnchorAnatomy ? "anchor" : undefined}
        aria-hidden
        style={style}
        className={cn(trackHighlightStructureClasses, className)}
      >
        {children}
      </div>
      {layered ? (
        <div
          ref={hoverRef}
          data-control-ui="track-highlight"
          data-control-family="track-highlight"
          data-slot="hover"
          aria-hidden
          style={style}
          className={cn(trackHighlightStructureClasses, hoverClassName)}
        />
      ) : null}
    </>
  );
}

@layer components {
  :where([data-control-family="track-highlight"][data-slot="root"]),
  :where([data-control-family="track-highlight"][data-slot="hover"]) {
    --_track-highlight-opacity: 0;
    border-radius: var(--cui-track-highlight-radius);
    opacity: var(--_track-highlight-opacity);
    transition-property: top, left, right, bottom, width, height, opacity, background-color, box-shadow;
    transition-duration: var(--cui-track-highlight-transition-duration);
    transition-timing-function: var(--ease-emphasized);
  }

  :where([data-control-family="track-highlight"][data-slot="root"]) {
    --cui-track-highlight-background: var(--card);
    --cui-track-highlight-hover-background: color-mix(in oklab, var(--card) 92%, var(--foreground) 8%);
    --cui-track-highlight-radius: var(--radius-popup-item);
    --cui-track-highlight-ring-color: oklch(from var(--foreground) l c h / 0.05);
    --cui-track-highlight-shadow: var(--shadow-sm);
    --cui-track-highlight-transition-duration: var(--duration-fast);
    background: var(--cui-track-highlight-background);
    box-shadow:
      0 0 0 1px var(--cui-track-highlight-ring-color),
      var(--cui-track-highlight-shadow);
  }

  :where([data-control-family="track-highlight"][data-slot="root"][data-hover]),
  :where([data-track="hover"] > [data-control-family="track-highlight"][data-slot="root"]) {
    --cui-track-highlight-background: var(--cui-track-highlight-hover-background);
    --cui-track-highlight-ring-color: transparent;
    --cui-track-highlight-shadow: none;
  }

  :where([data-control-family="track-highlight"][data-slot="hover"]) {
    background: var(--cui-track-highlight-hover-background);
  }

  :where([data-control-family="track-highlight"][data-slot="root"][data-visible]),
  :where([data-control-family="track-highlight"][data-slot="hover"][data-visible]) {
    --_track-highlight-opacity: 1;
  }

  :where(
    [data-track="hover"]:is([data-control-family="button-group"], [data-control-family="button"][data-slot="group"])
      > [data-control-family="track-highlight"]
  ) {
    --cui-track-highlight-hover-background: oklch(from var(--foreground) l c h / 0.06);
  }

  :where([data-track]:has(> [data-control-family="button"][data-track-item]) > [data-control-family="track-highlight"]),
  :where(
    [data-track]:is(
        [data-control-family="button-group"],
        [data-control-family="button"][data-slot="group"],
        [data-control-family="checkbox-group"]
      )
      > [data-control-family="track-highlight"]
  ) {
    --cui-track-highlight-radius: var(--radius-control);
  }

  @supports ((anchor-name: --cui-track) and (anchor-scope: --cui-track)) {
    :where([data-track]:has(> [data-control-family="track-highlight"])) {
      anchor-scope: --cui-track-active, --cui-track-hover, --cui-track-focus;
      --_track-anchor: --cui-track-active;
      --_track-display: none;
    }

    :where(
        [data-track="slide"]:has(> [data-control-family="track-highlight"]):has(
          [data-track-item][data-active="true"]:not(:disabled, [aria-disabled="true"], [data-disabled])
        )
      ) {
      --_track-display: block;
    }

    :where([data-track="hover"]:has(> [data-control-family="track-highlight"])) {
      --_track-anchor: --cui-track-idle;
    }

    :where(
        [data-track]:has(> [data-control-family="track-highlight"])
          [data-track-item][data-active="true"]:not(:disabled, [aria-disabled="true"], [data-disabled])
      ) {
      anchor-name: --cui-track-active;
    }

    :where([data-track] > [data-control-family="track-highlight"][data-positioning="anchor"]:not([data-measured])) {
      display: var(--_track-display);
      position-anchor: var(--_track-anchor);
      top: anchor(top, 0px);
      width: anchor-size(width, 0px);
      height: anchor-size(height, 0px);
      left: anchor(left, 0px);
      --_track-highlight-opacity: 1;

      @starting-style {
        opacity: 0;
      }
    }

    @media (hover: hover) {
      :where(
          [data-track]:has(> [data-control-family="track-highlight"])
            [data-track-item]:hover:not(:disabled, [aria-disabled="true"], [data-disabled], :has([role="checkbox"][data-disabled]))
        ) {
        anchor-name: --cui-track-hover;
      }

      :where(
          [data-track]:has(> [data-control-family="track-highlight"]):has(
            [data-track-item]:hover:not(:disabled, [aria-disabled="true"], [data-disabled])
          ):not(:has([data-track-item]:hover [role="checkbox"][data-disabled])):not(:has([data-track] [data-track-item]:hover))
        ) {
        --_track-anchor: --cui-track-hover;
        --_track-display: block;
      }

      :where(
          [data-track="slide"]:has(
              [data-track-item]:hover:not([data-active="true"], :disabled, [aria-disabled="true"], [data-disabled])
            ):not(:has(:focus-visible, [data-track] [data-track-item]:hover))
            > [data-control-family="track-highlight"][data-positioning="anchor"]:not([data-measured])
        ) {
        --cui-track-highlight-background: var(--cui-track-highlight-hover-background);
        --cui-track-highlight-ring-color: transparent;
        --cui-track-highlight-shadow: none;
      }
    }

    :where(
        [data-track]:has(> [data-control-family="track-highlight"])
          [data-track-item]:is(:focus-visible, :has(:focus-visible)):not(
            :disabled,
            [aria-disabled="true"],
            [data-disabled],
            :has([role="checkbox"][data-disabled])
          )
      ) {
      anchor-name: --cui-track-focus;
    }

    :where(
        [data-track]:has(> [data-control-family="track-highlight"]):has(
          [data-track-item]:focus-visible,
          [data-track-item] :focus-visible
        ):not(:has([data-track] :focus-visible))
      ) {
      --_track-anchor: --cui-track-focus;
      --_track-display: block;
    }

    :where(
        [data-track="slide"]:has(
            [data-track-item]:not([data-active="true"]):focus-visible,
            [data-track-item]:not([data-active="true"]) :focus-visible
          ):not(:has([data-track] :focus-visible))
          > [data-control-family="track-highlight"][data-positioning="anchor"]:not([data-measured])
      ) {
      --cui-track-highlight-background: var(--cui-track-highlight-hover-background);
      --cui-track-highlight-ring-color: transparent;
      --cui-track-highlight-shadow: none;
    }
  }
}

